// shared_modals.js
// Custom glassmorphic modals generated by Stitch MCP to replace native browser popups
(function() {
    const modalHTML = `
    <!-- Global Modal Container -->
    <div id="appModalContainer" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/60 backdrop-blur-sm p-4 text-left">
        
        <!-- Alert Modal -->
        <div id="appAlertModal" class="hidden bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-10 shadow-2xl relative overflow-hidden group w-full max-w-sm mx-auto">
            <div class="absolute -top-12 -right-12 w-32 h-32 bg-primary/10 rounded-full blur-3xl"></div>
            <div class="flex flex-col items-center text-center space-y-6 relative z-10">
                <div class="w-16 h-16 rounded-2xl bg-primary/20 flex items-center justify-center border border-primary/30 shadow-[0_0_20px_rgba(6,232,249,0.2)]">
                    <span class="material-symbols-outlined text-primary text-4xl font-light">info</span>
                </div>
                <div class="space-y-2">
                    <h3 id="appAlertTitle" class="text-2xl font-bold text-white">Information</h3>
                    <p id="appAlertDesc" class="text-slate-400 leading-relaxed whitespace-pre-wrap">Message</p>
                </div>
                <button id="appAlertBtn" class="w-full py-4 bg-primary text-background-dark font-bold rounded-2xl shadow-[0_0_25px_rgba(6,232,249,0.4)] hover:shadow-primary/60 transition-all active:scale-[0.98]">
                    Got it
                </button>
            </div>
        </div>

        <!-- Confirm Modal -->
        <div id="appConfirmModal" class="hidden bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-10 shadow-2xl relative overflow-hidden w-full max-w-sm mx-auto text-left">
            <div class="absolute -top-12 -left-12 w-32 h-32 bg-accent-purple/10 rounded-full blur-3xl"></div>
            <div class="flex flex-col items-center text-center space-y-6 relative z-10">
                <div class="w-16 h-16 rounded-2xl bg-accent-purple/20 flex items-center justify-center border border-accent-purple/30 shadow-[0_0_20px_rgba(168,85,247,0.2)]">
                    <span class="material-symbols-outlined text-accent-purple text-4xl font-light">warning</span>
                </div>
                <div class="space-y-2">
                    <h3 id="appConfirmTitle" class="text-2xl font-bold text-white">Are you sure?</h3>
                    <p id="appConfirmDesc" class="text-slate-400 leading-relaxed whitespace-pre-wrap">This action cannot be undone.</p>
                </div>
                <div class="flex w-full gap-4 pt-2">
                    <button id="appConfirmCancel" class="flex-1 py-4 bg-white/5 text-slate-100 font-semibold rounded-2xl border border-white/10 hover:bg-white/10 transition-colors">
                        Cancel
                    </button>
                    <button id="appConfirmOk" class="flex-1 py-4 bg-accent-purple text-white font-bold rounded-2xl shadow-[0_0_25px_rgba(168,85,247,0.4)] hover:shadow-accent-purple/60 transition-all active:scale-[0.98]">
                        Confirm
                    </button>
                </div>
            </div>
        </div>

        <!-- Prompt Modal -->
        <div id="appPromptModal" class="hidden bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-10 shadow-2xl relative w-full max-w-sm mx-auto text-left">
            <div class="flex flex-col space-y-6 relative z-10">
                <div class="space-y-2 text-center">
                    <h3 id="appPromptTitle" class="text-2xl font-bold text-white">Input Required</h3>
                    <p id="appPromptDesc" class="text-slate-400 whitespace-pre-wrap block" style="display:block;"></p>
                </div>
                <div class="space-y-4">
                    <div class="group">
                        <input id="appPromptInput" class="w-full bg-black/20 border border-white/10 rounded-xl px-4 py-4 text-slate-100 placeholder:text-slate-600 focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary shadow-inner transition-all" type="text" />
                    </div>
                </div>
                <div class="flex gap-4 pt-2">
                    <button id="appPromptCancel" class="flex-1 py-4 text-slate-400 font-semibold rounded-2xl hover:bg-white/5 transition-colors">
                        Cancel
                    </button>
                    <button id="appPromptOk" class="flex-1 py-4 bg-primary text-background-dark font-bold rounded-2xl shadow-[0_0_20px_rgba(6,232,249,0.3)] hover:shadow-primary/50 transition-all">
                        Save
                    </button>
                </div>
            </div>
        </div>

    </div>
    `;

    // Wait until body is present
    document.addEventListener("DOMContentLoaded", () => {
        document.body.insertAdjacentHTML('beforeend', modalHTML);
    });
    // Fallback if already loaded
    if(document.body) {
        if(!document.getElementById('appModalContainer')) {
            document.body.insertAdjacentHTML('beforeend', modalHTML);
        }
    }

    function hideAll() {
        const container = document.getElementById('appModalContainer');
        container.classList.add('hidden');
        container.classList.remove('flex');
        document.getElementById('appAlertModal').classList.add('hidden');
        document.getElementById('appConfirmModal').classList.add('hidden');
        document.getElementById('appPromptModal').classList.add('hidden');
    }

    window.showAppAlert = function(msg, title = 'Information') {
        document.getElementById('appAlertTitle').textContent = title;
        document.getElementById('appAlertDesc').textContent = msg;
        
        const container = document.getElementById('appModalContainer');
        container.classList.remove('hidden');
        container.classList.add('flex');
        document.getElementById('appAlertModal').classList.remove('hidden');

        return new Promise(resolve => {
            const btn = document.getElementById('appAlertBtn');
            btn.onclick = () => {
                hideAll();
                resolve();
            };
        });
    };

    window.showAppConfirm = function(msg, title = 'Are you sure?') {
        document.getElementById('appConfirmTitle').textContent = title;
        document.getElementById('appConfirmDesc').textContent = msg;

        const container = document.getElementById('appModalContainer');
        container.classList.remove('hidden');
        container.classList.add('flex');
        document.getElementById('appConfirmModal').classList.remove('hidden');

        return new Promise(resolve => {
            document.getElementById('appConfirmOk').onclick = () => { hideAll(); resolve(true); };
            document.getElementById('appConfirmCancel').onclick = () => { hideAll(); resolve(false); };
        });
    };

    window.showAppPrompt = function(msg, defaultValue = '', title = 'Input Required') {
        document.getElementById('appPromptTitle').textContent = title;
        document.getElementById('appPromptDesc').textContent = msg;
        
        const input = document.getElementById('appPromptInput');
        input.value = defaultValue;

        const container = document.getElementById('appModalContainer');
        container.classList.remove('hidden');
        container.classList.add('flex');
        document.getElementById('appPromptModal').classList.remove('hidden');
        input.focus();

        return new Promise(resolve => {
            document.getElementById('appPromptOk').onclick = () => { hideAll(); resolve(input.value); };
            document.getElementById('appPromptCancel').onclick = () => { hideAll(); resolve(null); };
        });
    };
})();
